import React from "react";
import {MenuList} from "../data/data"
import Layout from "../Components/Layout/Layout";
import { Box, Card, CardActionArea, CardContent, CardMedia, Typography } from "@mui/material";
import {Link} from 'react-router-dom'
import Button from '@mui/material/Button';
const Menu = () => {
  const btnStyle = { margin: "20px 20vh" ,width:"110px",}
  return (
    <Layout>
      <Box sx={{display:"flex",flexWrap:"wrap",background:"gold",justifyContent:"center"}}>
{MenuList.map((menu) => (

    <Card sx={{maxWidth:"390px",display:"flex",m:2}}>
      <CardActionArea>
        <CardMedia sx={{minHeight:"400px"}} 
        component={"img"}
        src={menu.image}
         alt={menu.name}/>
        
           <Link to='https://dialameal.in/restaurant-Cuisines/7'>
      <Button type="button" variant="contained" color="success"  style={btnStyle} fullWidth >click me </Button>
      </Link>
         <CardContent>
          <Typography variant="h5"gutterBottom component={"div"}>
            {menu.name}
          </Typography>
          <Typography variant="body2">
            {menu.Description}
          </Typography>
         </CardContent>
      </CardActionArea>
    </Card>
  ))
}
      </Box>
    </Layout>
  );
};

export default Menu;
