import React from "react";
import Layout from "./../Components/Layout/Layout";
import {Link} from "react-router-dom";
import Banner from "../images/Food.jpg";
import pick from "../images/rasturent.jpeg";
import "../Styles/HomeStyle.css";
import Card from '@mui/material/Card';
import CardActions from '@mui/material/CardActions';
import CardContent from '@mui/material/CardContent';
import CardMedia from '@mui/material/CardMedia';
import Button from '@mui/material/Button';
import Typography from '@mui/material/Typography';

const Home = () => {
    return (
        <Layout>
            <div className="home" style = {{backgroundImage:`url(${Banner})` }}>
                <div className ="headerContainer">
                    <h1>Best website</h1>
                    <p>Best food of india</p>
                    <Link to ="/menu">
                    <button >
                       ORDER NO 
                       </button>
                    </Link> 
                </div>   
            </div>
            <Card sx={{ maxWidth: 320,height:"390px",m:"20px 0px" }}>
      <CardMedia
        sx={{ height: 200 }}
        style = {{backgroundImage:`url(${pick})` }}
      />
      <CardContent>
        <Typography gutterBottom variant="h5" component="div">
          rasturent
        </Typography>
        <Typography variant="body2" color="text.secondary">
        A restaurant is a business that prepares and serves food and 
        drinks to customers. Meals are generally served and 
        eaten on the premises, 
        </Typography>
      </CardContent>
      <CardActions href="https://google.com">
        <Button size="small">Share</Button>
        <Button size="small">Learn More</Button>
      </CardActions>
    </Card>
        </Layout>
    );
};

export default Home;
