import { Grid, Paper, TextField, Typography, Link } from "@mui/material";
import React, { useState } from 'react';
import FormControlLabel from '@mui/material/FormControlLabel';
import Checkbox from '@mui/material/Checkbox';
import Button from '@mui/material/Button';
import { useNavigate } from "react-router-dom";
//import Box from '@mui/material/Box';
const RegisterForm = () => {
    const navigate = useNavigate();
    const [username, setUsername] = useState('');
    const [usernameError, setUsernameError] = useState();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [emailError, setEmailError] = useState();
    const [passwordError, setPasswordError] = useState();

    const handleEmailChange = (e) => {
        setEmail(e.target.value)
        if (!validateEmail(e.target.value)) {
            setEmailError("please enter valid email")
        }
        else {
            setEmailError("");
        };
    };

    const handleUsernameChange = (e) => {
        setUsername(e.target.value)
        if (e.target.value) {
            setUsernameError("please enter valid username")
        }
        else {
            setUsernameError("");
        };
    };


    const validateEmail = (email) => {
        const emailRegex = /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,4}$/i;
        return emailRegex.test(email)
    }

    const handlePasswordChange = (e) => {
        setPassword(e.target.value)
        if (e.target.value.length < 6) {
            setPasswordError("Password must be atleast 6 characters")

        }
        else {
            setPasswordError("");
        };
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        if (email && password && !(emailError) && !(passwordError))
            alert("account create successfuly");

        //  navigate to /
        navigate('/home');
    }

    const paperStyle = { padding: 20, height: "70vh", width: 280, margin: "20px auto", }
    const btnStyle = { margin: "10px 0px" }
    return (
        <div>
            <form onSubmit={handleSubmit} >
                <Grid>
                    <Paper elevation={10} sx={{ bgcolor: "wheat" }} style={paperStyle}>
                        <Grid align="center">
                            <h1>Login</h1>
                        </Grid >
                        <TextField
                            placeholder="Enter Username "
                            variant="standard"
                            label="Username"
                            fullWidth
                            onChange={handleUsernameChange}
                            value={username}
                            error={usernameError}
                            required
                        />

                        <TextField label="useremail" variant="standard" placeholder="Enter username " onChange={handleEmailChange}
                            value={email}
                            error={emailError} fullWidth required />
                        <TextField label="Password" variant="standard" placeholder="Enter password " type="password"
                            onChange={handlePasswordChange}
                            value={password}
                            error={passwordError} fullWidth required />
                        <FormControlLabel required control={<Checkbox />} label="Required" />
                        <Typography>
                            <Button type="submit" variant="contained" color="success" style={btnStyle}
                                fullWidth Required >
                                Login
                            </Button>
                        </Typography>
                        <Typography>
                            <Link href="#" >
                                Forget password ?
                            </Link>
                        </Typography>
                        <Typography> do you have an account ?
                            <Link href="Signup" >
                                signUp ?
                            </Link>
                        </Typography>
                    </Paper>
                </Grid>
            </form>
        </div>
    )
}

export default RegisterForm;
